SELECT n.id, n.title, n.content, n.type, n.status, n.level, n.is_delete, n.create_by, n.create_time, n.update_by, n.update_time, kbn.knowledge_base_id FROM ntc_notice n INNER JOIN ntc_knowledge_base_notice kbn ON kbn.notice_id = n.id WHERE n.type = 1 AND n.status = 0 AND n.is_delete = 0 AND n.id IN
#{id}
ORDER BY n.id ASC
